package com.acxiom.crm.audit; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller public class AuditController {private final AuditRepository repo; public AuditController(AuditRepository r){repo=r;} @GetMapping("/admin/audit") public String list(@RequestParam(required=false) String module,Model m){var rows=repo.findAll().stream().filter(a->module==null||module.isBlank()||a.getModule().equalsIgnoreCase(module)).toList();m.addAttribute("logs",rows);m.addAttribute("module",module==null?"":module);return "audit";} }
